const cfg = $input.first().json;
const now = new Date();
const since = new Date(now.getTime() - cfg.LOOKBACK_DAYS * 24 * 60 * 60 * 1000);

const bots = cfg.AI_BOTS_TO_TRACK.split(',').map(b => b.trim()).filter(Boolean);
const orFilters = bots.map(b => `{ userAgent_like: "%${b}%" }`).join(',\n            ');

const query = `query GetAiCrawlerRequests($zoneTag: string, $since: string, $until: string) {
  viewer {
    zones(filter: { zoneTag: $zoneTag }) {
      httpRequestsAdaptiveGroups(
        filter: {
          datetime_geq: $since,
          datetime_leq: $until,
          requestSource: "eyeball",
          OR: [
            ${orFilters}
          ]
        },
        limit: 5000,
        orderBy: [count_DESC]
      ) {
        count
        dimensions {
          userAgent
          edgeResponseStatus
        }
      }
    }
  }
}`;

return [{
  json: {
    query,
    variables: {
      zoneTag: cfg.CLOUDFLARE_ZONE_ID,
      since: since.toISOString(),
      until: now.toISOString()
    }
  }
}];

const cfg = $('CONFIG - Edit Me First').first().json;
const groups = $input.first().json.data?.viewer?.zones?.[0]?.httpRequestsAdaptiveGroups || [];
const knownBots = cfg.AI_BOTS_TO_TRACK.split(',').map(b => b.trim()).filter(Boolean);

function extractBotName(ua) {
  for (const bot of knownBots) {
    if (ua.includes(bot)) return bot;
  }
  return 'Other';
}

const activity = {};
for (const g of groups) {
  const ua = g.dimensions.userAgent || '';
  const bot = extractBotName(ua);
  activity[bot] = (activity[bot] || 0) + g.count;
}

return [{
  json: {
    siteName: cfg.SITE_NAME,
    lookbackDays: cfg.LOOKBACK_DAYS,
    activity,
    language: cfg.LANGUAGE,
    enableEmail: cfg.ENABLE_EMAIL,
    enableTelegram: cfg.ENABLE_TELEGRAM,
    alertEmail: cfg.ALERT_EMAIL,
    telegramChatId: cfg.TELEGRAM_CHAT_ID
  }
}];

